async fetch(request: Request, env: Env): Promise<Response> {
  const url = new URL(request.url);

  // ==========================================
  // 1. 管理画面 GET /
  // ==========================================
  if (url.pathname === "/" && request.method === "GET") {
    addLog("管理画面へのアクセスを検出");

    // KVからデバッグログを取得
    const raw = await env.PHONE_STORE.get('debug_logs');
    const logs = raw ? JSON.parse(raw) : [];

    // KVから最終イベント情報を取得
    const lastEventRaw = await env.PHONE_STORE.get('last_event_info');
    const lastEventInfo: LastEventInfo = lastEventRaw ? JSON.parse(lastEventRaw) : emptyLastEventInfo();

    // KVからアップロード結果を取得
    const uploadResults: UploadDebugResult[] = [];
    const keys = await env.PHONE_STORE.list({ prefix: "upload_result:" });
    for (const key of keys.keys) {
      const resultRaw = await env.PHONE_STORE.get(key.name);
      if (resultRaw) {
        uploadResults.push(JSON.parse(resultRaw));
      }
    }

    // HTMLを生成
    const html = generateDashboardHTML(logs, lastEventInfo, uploadResults);
    return new Response(html, {
      headers: { "Content-Type": "text/html;charset=UTF-8" },
    });
  }
}
```

